/* usage.js — usage bar rendering, sparklines, countdown. Loaded before app.js. */

let _usageData = null;
let _quotaMapData = null;
let _usageError = false;
let _usageCountdownInterval = null;
let _usageFetchPromise = null;
let _usageLastSuccessAt = 0;
let _usageLastFetchStartedAt = 0;
const _USAGE_REFRESH_INTERVAL_MS = 120000;
const _USAGE_CLICK_DEBOUNCE_MS = 1000;

// Color encodes pace vs. ideal burn rate: green = under budget, red = over,
// yellow = on track. When resetPct is known, diff drives color rather than raw %.
function _usageColor(usagePct, resetPct) {
    if (resetPct == null) {
        if (usagePct >= 80) return '#ef4444';
        if (usagePct >= 50) return '#eab308';
        return '#22c55e';
    }
    const diff = usagePct - resetPct;
    if (diff < -10) return '#22c55e';
    if (diff > 10) return '#ef4444';
    // Smooth hue transition between yellow (60°) and red/green for near-ideal pace
    const hue = Math.max(0, Math.min(120, 60 - diff * 6));
    return `hsl(${hue}, 80%, 50%)`;
}

function _resetCountdown(isoStr) {
    if (!isoStr) return '';
    const ms = new Date(isoStr) - Date.now();
    if (ms <= 0) return '';
    const h = Math.floor(ms / 3600000); const m = Math.floor((ms % 3600000) / 60000);
    if (h >= 24) { const d = Math.floor(h / 24); return `${d}d ${h % 24}h ${m}m`; }
    return `${h}h ${m}m`;
}

function _resetPctNum(isoStr, windowMs) {
    if (!isoStr) return null;
    const remaining = new Date(isoStr) - Date.now();
    const elapsed = windowMs - remaining;
    return Math.max(0, Math.min(100, Math.round(elapsed / windowMs * 100)));
}

// Computes how long to wait (or "ok") based on pace vs. ideal linear burn.
// cooldownMin = how many minutes to wait at 0% usage to get back on pace.
function _paceIndicator(currentPct, isoStr, windowMs) {
    if (!isoStr) return '';
    const remainMs = Math.max(0, new Date(isoStr) - Date.now());
    const elapsedMs = windowMs - remainMs;
    const idealPct = (elapsedMs / windowMs) * 100;
    const delta = currentPct - idealPct;
    if (delta <= 5) return '<span style="color:#22c55e" title="Расход не опережает линейный темп окна">темп ok</span>';
    const cooldownMin = Math.round(delta * windowMs / 100 / 60000);
    const color = delta <= 20 ? '#eab308' : '#ef4444';
    let label;
    if (cooldownMin < 60) label = `${cooldownMin}m`;
    else if (cooldownMin < 1440) label = `${Math.floor(cooldownMin/60)}h ${cooldownMin%60}m`;
    else label = `${Math.floor(cooldownMin/1440)}d ${Math.floor((cooldownMin%1440)/60)}h ${cooldownMin%60}m`;
    return `<span style="color:${color}" title="Локальная оценка опережения линейного темпа. Это не отдельное лимитное окно и не официальный таймер провайдера.">темп +${label}</span>`;
}

function _releaseDurationFromSeconds(totalSeconds) {
    const rounded = Math.max(0, Math.round(Number(totalSeconds)));
    if (!Number.isFinite(rounded)) return '';
    if (rounded < 60) return `${rounded}m`;
    const minutes = Math.floor((rounded % 3600) / 60);
    const hours = Math.floor((rounded % 86400) / 3600);
    const days = Math.floor(rounded / 86400);
    if (days > 0) return `${days}d ${hours}h ${minutes}m`;
    if (hours > 0) return `${hours}h ${minutes}m`;
    return `${minutes}m`;
}

function _quotaWindowMatch(bucketWindow, candidate) {
    if (!bucketWindow || !candidate || !candidate.id) return false;
    if (String(bucketWindow.id) !== String(candidate.id)) return false;
    if (Number(bucketWindow.window_minutes) !== Number(candidate.window_minutes)) return false;

    const bucketReset = Date.parse(bucketWindow.resets_at);
    const candidateReset = Date.parse(candidate.resets_at);
    if (Number.isFinite(bucketReset) && Number.isFinite(candidateReset)) {
        return Math.abs(bucketReset - candidateReset) <= 1000;
    }
    return String(bucketWindow.resets_at || '') === String(candidate.resets_at || '');
}

function _quotaMapLaneRelease(windowData, bucketId = null) {
    if (!_quotaMapData || !_quotaMapData.buckets) {
        return {status: 'no_data', release_in_seconds: null};
    }
    const buckets = _quotaMapData.buckets.filter(item => !bucketId || item.bucket === bucketId);
    const chooseLane = (bucket) => Array.isArray(bucket?.lanes)
        ? (bucket.lanes.find(item => item?.gated) || bucket.lanes[0])
        : null;
    const laneRelease = (bucket) => {
        if (!bucket) return {status: 'no_data', release_in_seconds: null};
        const lane = chooseLane(bucket);
        if (!lane) return {status: 'open', release_in_seconds: null};
        return {
            status: String(lane.release_status || (lane.blocked ? 'at_reset' : 'open')),
            release_in_seconds: Number(lane.release_in_seconds),
        };
    };
    if (!windowData) {
        const bucket = buckets[0];
        return bucket && bucket.data_available && bucket.window ? laneRelease(bucket) : {status: 'no_data', release_in_seconds: null};
    }

    const exact = buckets.filter(item => _quotaWindowMatch(item.window, windowData));
    const throughReference = exact.length
        ? exact
        : buckets.filter(item => (item.reference_windows || [])
            .some(window => _quotaWindowMatch(window, windowData)));

    const bucket = throughReference.length === 1
        ? throughReference[0]
        : throughReference.find(item => item.data_available && item.window && String(item.window.id) === String(windowData.id))
            || buckets.find(item => item.data_available && item.bucket === bucketId && item.window && item.window.id);
    if (!bucket) return {status: 'no_data', release_in_seconds: null};
    if (!bucket.data_available || !bucket.window || !bucket.window.id) {
        return {status: 'no_data', release_in_seconds: null};
    }
    return laneRelease(bucket);
}

function _quotaMapLaneStatusText(windowData, bucketId = null) {
    const {status, release_in_seconds} = _quotaMapLaneRelease(windowData, bucketId);
    const seconds = Number(release_in_seconds);
    const hasSeconds = Number.isFinite(seconds);
    if (status === 'opens_in') {
        return hasSeconds ? `откроется через ${_releaseDurationFromSeconds(seconds)}` : 'откроется скоро';
    }
    if (status === 'at_reset') {
        return hasSeconds ? `откроется при сбросе, через ${_releaseDurationFromSeconds(seconds)}` : 'откроется при сбросе';
    }
    if (status === 'no_data') {
        return 'нет данных';
    }
    return 'работает';
}

function _etaToLimit(currentPct, isoStr, windowMs) {
    if (!isoStr || currentPct <= 0) return '';
    const remainMs = Math.max(0, new Date(isoStr) - Date.now());
    const elapsedMs = windowMs - remainMs;
    if (elapsedMs <= 0) return '';
    const rate = currentPct / elapsedMs;
    const pctLeft = 100 - currentPct;
    if (pctLeft <= 0) return '<span style="color:#ef4444">⚡ лимит!</span>';
    const etaMs = pctLeft / rate;
    const etaMin = Math.round(etaMs / 60000);
    const color = etaMin < 30 ? '#ef4444' : etaMin < 120 ? '#eab308' : '#22c55e';
    let label;
    if (etaMin < 60) label = `${etaMin}m`;
    else if (etaMin < 1440) label = `${Math.floor(etaMin/60)}h ${etaMin%60}m`;
    else label = `${Math.floor(etaMin/1440)}d ${Math.floor((etaMin%1440)/60)}h`;
    return `<span style="color:${color}">⏳${label}</span>`;
}

function _miniBar(pct, color) {
    return `<span style="display:inline-flex;align-items:center;gap:4px"><span style="position:relative;display:inline-block;width:80px;height:6px;border-radius:3px;background:rgba(51,65,85,0.5);overflow:hidden;vertical-align:middle"><span style="display:block;width:${Math.min(pct, 100)}%;height:100%;border-radius:3px;background:${color}"></span></span><span style="color:#e2e8f0;font-weight:600">${pct}%</span></span>`;
}

function _codexWindowLabel(windowMinutes) {
    if (windowMinutes === 300) return '5h';
    if (windowMinutes === 10080) return '7d';
    if (windowMinutes % 1440 === 0) return `${windowMinutes / 1440}d`;
    if (windowMinutes % 60 === 0) return `${windowMinutes / 60}h`;
    return `${windowMinutes}m`;
}

function _usageProviderAccent(providerId) {
    const meta = _PROVIDER_META[providerId] || {};
    return meta.usageAccent || _PROVIDER_COLORS[meta.provider] || _PROVIDER_COLORS.unknown;
}

function _usageProviderWindows(providerId, capacity) {
    const meta = _PROVIDER_META[providerId];
    return meta.windows(capacity || {})
        .filter(([, window]) => window)
        .map(([label, window, defaultMinutes]) => ({
            label,
            window: defaultMinutes && !window.window_minutes
                ? {...window, window_minutes:defaultMinutes}
                : window,
        }));
}

function _usageFreshnessHtml() {
    if (_usageFetchPromise) {
        return '<span id="usage-freshness" style="color:#38bdf8">обновление…</span>';
    }
    if (!_usageLastSuccessAt) return '';
    const ageMinutes = Math.floor((Date.now() - _usageLastSuccessAt) / 60000);
    const age = ageMinutes < 1 ? 'сейчас' : `${ageMinutes} мин назад`;
    if (_usageError) {
        return `<span id="usage-freshness" style="color:#eab308">ошибка обновления · данные от ${age}</span>`;
    }
    const stale = Date.now() - _usageLastSuccessAt >= _USAGE_REFRESH_INTERVAL_MS;
    return `<span id="usage-freshness" style="color:${stale ? '#eab308' : '#64748b'}">${stale ? 'устарело' : 'обновлено'} ${age}</span>`;
}

function _renderUsageBarShell(bar, groups) {
    bar.innerHTML = `<div class="usage-limits">${groups.join('')}</div>`
        + `<div class="usage-actions">${_usageFreshnessHtml()}`
        + '<span id="usage-info-btn" title="Usage details and history">ⓘ</span></div>';
}

function renderUsageBar() {
    const bar = document.getElementById('usage-bar');
    if (!bar) return;
    if (!_usageData) {
        if (_usageError) {
            bar.style.cssText = 'display:flex;align-items:center;padding:0 12px;height:28px;background:#0f172a;border-bottom:1px solid rgba(30,41,59,0.5);font-size:11px;color:#eab308;flex-shrink:0';
            bar.textContent = '⚠ Usage unavailable';
        } else {
            bar.innerHTML = '';
            bar.style.display = 'none';
        }
        return;
    }
    bar.style.cssText = 'display:flex;align-items:flex-start;gap:10px;padding:4px 12px;min-height:28px;height:auto;background:#0f172a;border-bottom:1px solid rgba(30,41,59,0.5);font-size:11px;color:#94a3b8;flex-shrink:0;overflow:visible;white-space:nowrap;cursor:pointer';
    bar.title = 'Нажмите, чтобы обновить usage';

    const a = _usageData.anthropic || {};
    const cx = _usageData.codex || {};
    const gx = _usageData.grok || null;
    const groups = [];
    const claudeParts = [];

    if (_usageError) claudeParts.push('<span style="color:#eab308" title="Using cached data">⚠️</span>');

    const fh = a.five_hour;
    if (fh) {
        const rpNum = _resetPctNum(fh.resets_at, 5 * 3600000);
        const c = _usageColor(fh.utilization, rpNum);
        const rp = rpNum != null ? ` <span style="color:#64748b">(${rpNum}%)</span>` : '';
        const cd = _resetCountdown(fh.resets_at);
        const release = '';
        claudeParts.push(`<span style="display:inline-flex;align-items:center;gap:3px">5h: ${_miniBar(fh.utilization, c)}${rp}${cd ? ` <span style="color:#64748b">${cd}</span>` : ''}${release ? ` <span style="font-size:10px">·</span> ${release}` : ''}</span>`);
    }
    const sd = a.seven_day;
    if (sd) {
        const rpNum = _resetPctNum(sd.resets_at, 7 * 86400000);
        const c = _usageColor(sd.utilization, rpNum);
        const rp = rpNum != null ? ` <span style="color:#64748b">(${rpNum}%)</span>` : '';
        const cd = _resetCountdown(sd.resets_at);
        const release = _quotaMapLaneStatusText(sd, 'anthropic');
        claudeParts.push(`<span style="display:inline-flex;align-items:center;gap:3px">7d: ${_miniBar(sd.utilization, c)}${rp}${cd ? ` <span style="color:#64748b">${cd}</span>` : ''}${release ? ` <span style="font-size:10px">·</span> ${release}` : ''}</span>`);
    }
    if (claudeParts.length) {
        groups.push(`<span class="usage-provider-group" data-usage-compact-provider="claude">${claudeParts.join('')}</span>`);
    }

    const compactProviders = [
        {id:'codex', bucketId:'codex', windows:_usageProviderWindows('codex', cx)},
        {id:'codex', bucketId:'codex_spark', windows:_usageProviderWindows('codex', cx.spark), compactTitle:'Codex Spark'},
        {id:'grok', bucketId:'grok', windows:_usageProviderWindows('grok', gx), showUnavailable:true},
    ].filter(provider => provider.windows.length || provider.showUnavailable);
    if (compactProviders.length) {
        for (const provider of compactProviders) {
            const meta = _PROVIDER_META[provider.id];
            const color = _usageProviderAccent(provider.id);
            const providerParts = [
                '<span style="height:14px;border-left:1px solid rgba(71,85,105,0.6)"></span>',
                `<span style="color:${color};font-weight:600">${provider.compactTitle || meta.compactTitle || meta.title}</span>`,
            ];
            if (!provider.windows.length) {
                providerParts.push('<span style="color:#64748b">: нет данных</span>');
                groups.push(`<span class="usage-provider-group" data-usage-compact-provider="${provider.id}">${providerParts.join('')}</span>`);
                continue;
            }
            for (const item of provider.windows) {
                const window = item.window;
                const windowMs = window.window_minutes * 60000;
                const rpNum = _resetPctNum(window.resets_at, windowMs);
                const c = _usageColor(window.utilization, rpNum);
                const rp = rpNum != null ? ` <span style="color:#64748b">(${rpNum}%)</span>` : '';
                const cd = _resetCountdown(window.resets_at);
                const release = _quotaMapLaneStatusText(window, provider.bucketId);
                const pace = _paceIndicator(window.utilization, window.resets_at, windowMs);
                const label = _codexWindowLabel(window.window_minutes);
                providerParts.push(`<span style="display:inline-flex;align-items:center;gap:3px">${label}: ${_miniBar(window.utilization, c)}${rp}${cd ? ` <span style="color:#64748b">${cd}</span>` : ''}${release ? ` <span style="font-size:10px">·</span> ${release}` : ''}</span>`);
            }
            groups.push(`<span class="usage-provider-group" data-usage-compact-provider="${provider.id}">${providerParts.join('')}</span>`);
